    let stamp = stampPath(marker)
    let app = launchedApp()
    focusTerminal(app)
    // `disown` detaches the backgrounded stamper from the shell's job table, so the shell exiting
    // doesn't wait on or reap it — enough to simulate "survives the app quitting" without touching a
    // single line of app or engine code.
    run(app, stamperCommand(marker: marker, stamp: stamp))

    XCTAssertTrue(
      pollUntilAdvancing(stamp),
      "setup failed: the marked stamper (\(marker)) never started touching \(stamp)")

    app.terminate()
    RunLoop.current.run(until: Date().addingTimeInterval(1))

    XCTAssertTrue(
      stampIsAdvancing(stamp, window: 2),
      "expected this to FAIL: a disowned stamper should still be touching its file after quit — if "
        + "it isn't, the detection mechanism itself is broken, not just insensitive to a real leak")
  }
}

